from path_guard import safe_join
from pathlib import Path
import tempfile
with tempfile.TemporaryDirectory() as td:
    root = Path(td) / 'root'; outside = Path(td) / 'outside'; root.mkdir(); outside.mkdir()
    (root / 'ok.txt').write_text('ok'); (outside / 'secret.txt').write_text('no')
    assert Path(safe_join(str(root), 'ok.txt')) == (root / 'ok.txt').resolve()
    assert Path(safe_join(str(root), '.')) == root.resolve()
    for bad in ('../outside/secret.txt', '/etc/passwd', 'a/../../x', 'bad\x00name'):
        try: safe_join(str(root), bad)
        except ValueError: pass
        else: raise AssertionError('escape aceptado: '+repr(bad))
    link = root / 'link'
    try: link.symlink_to(outside, target_is_directory=True)
    except (OSError, NotImplementedError): pass
    else:
        try: safe_join(str(root), 'link/secret.txt')
        except ValueError: pass
        else: raise AssertionError('symlink fuera aceptado')
